// entity 2 -- the switch. Solid, drawn, and pressable: the compiler folds this
// brush into static world geometry and also emits a use-activation trigger
// volume inflated by use_reach, so a player standing in front of the solid face
// still overlaps the volume.
{
"classname" "switch"
"name" "door_switch"
"on_fire" "switchDemo.openDoor"
"use_reach" "24"
"fire_mode" "once"
"rearm_ms" "0"
"enabled_on_spawn" "1"
